{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "section1_stack",
        "section2_stack",
        "section3_stack"
      ]
    },
    "section1_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "section1_header_stack",
        "section1_text"
      ]
    },
    "section1_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "section1_icon",
        "section1_title"
      ]
    },
    "section1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000606_01_2_graph-up.svg"
      },
      "children": []
    },
    "section1_title": {
      "type": "Text",
      "props": {
        "text": "Q4 2023 Website Traffic Overview",
        "variant": "h2"
      },
      "children": []
    },
    "section1_text": {
      "type": "Text",
      "props": {
        "text": "The website experienced consistent growth across key traffic sources throughout Q4 2023, with Organic Search leading as the primary driver of visits."
      },
      "children": []
    },
    "section2_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "section2_header_stack",
        "section2_text",
        "table1"
      ]
    },
    "section2_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "section2_icon",
        "section2_title"
      ]
    },
    "section2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000609_01_2_pie-chart.svg"
      },
      "children": []
    },
    "section2_title": {
      "type": "Text",
      "props": {
        "text": "Quarterly Traffic Source Distribution",
        "variant": "h2"
      },
      "children": []
    },
    "section2_text": {
      "type": "Text",
      "props": {
        "text": "This table illustrates the overall distribution of traffic sources for the entire quarter (October, November, December)."
      },
      "children": []
    },
    "table1": {
      "type": "Table",
      "props": {
        "title": "Q4 2023 Traffic Source Breakdown",
        "columns": [
          { "key": "Source", "label": "Source" },
          { "key": "Total Visits", "label": "Total Visits" }
        ],
        "rows": [
          { "Source": "Organic Search", "Total Visits": 48500 },
          { "Source": "Direct", "Total Visits": 25500 },
          { "Source": "Social Media", "Total Visits": 19500 },
          { "Source": "Referral", "Total Visits": 12700 }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "primaryColumn": "Source",
        "numericColumns": ["Total Visits"]
      },
      "children": []
    },
    "section3_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "section3_header_stack",
        "section3_text",
        "table2"
      ]
    },
    "section3_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "section3_icon",
        "section3_title"
      ]
    },
    "section3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000609_01_3_bar-chart.svg"
      },
      "children": []
    },
    "section3_title": {
      "type": "Text",
      "props": {
        "text": "Monthly Traffic Trends for Top Sources",
        "variant": "h2"
      },
      "children": []
    },
    "section3_text": {
      "type": "Text",
      "props": {
        "text": "This table highlights the monthly performance of the top two traffic sources, Organic Search and Direct, showing their individual trends over Q4 2023."
      },
      "children": []
    },
    "table2": {
      "type": "Table",
      "props": {
        "title": "Monthly Visits by Top Sources (Organic Search & Direct)",
        "columns": [
          { "key": "Month", "label": "Month" },
          { "key": "Source", "label": "Source" },
          { "key": "Visits", "label": "Visits" }
        ],
        "rows": [
          { "Month": "Oct", "Source": "Organic Search", "Visits": 15000 },
          { "Month": "Oct", "Source": "Direct", "Visits": 8000 },
          { "Month": "Nov", "Source": "Organic Search", "Visits": 16500 },
          { "Month": "Nov", "Source": "Direct", "Visits": 8500 },
          { "Month": "Dec", "Source": "Organic Search", "Visits": 17000 },
          { "Month": "Dec", "Source": "Direct", "Visits": 9000 }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "primaryColumn": "Month",
        "highlightColumns": ["Visits"],
        "numericColumns": ["Visits"]
      },
      "children": []
    }
  }
}
